import{_ as r,a0 as l,w as p,s as u,ao as i,I as a,x as e,a1 as o,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const N=JSON.parse('{"title":"在你的 Linux KDE 桌面上粘贴便签 | LCTT x X-CMD","titleTemplate":false,"description":"在你的 Linux KDE 桌面上粘贴便签 | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在你的 Linux KDE 桌面上粘贴便签 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在你的 Linux KDE 桌面上粘贴便签 | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20220228 Put sticky notes on your Linux KDE desktop","title":"在你的 Linux KDE 桌面上粘贴便签","tag":"202203","desc":""},"relativePath":"202203/20220228 Put sticky notes on your Linux KDE desktop.md","filePath":"[post].md"}'),d={name:"202203/20220228 Put sticky notes on your Linux KDE desktop.md"};function m(f,t,k,K,x,b){const s=l("Link");return p(),u("div",null,[t[20]||(t[20]=i('<h1 id="在你的-linux-kde-桌面上粘贴便签" tabindex="-1">在你的 Linux KDE 桌面上粘贴便签 <a class="header-anchor" href="#在你的-linux-kde-桌面上粘贴便签" aria-label="Permalink to “在你的 Linux KDE 桌面上粘贴便签”">​</a></h1><blockquote><p>使用 Kontact 套件的功能 KNotes 温和地提醒你自己的日常任务。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202203/11/083349wujq4dbh6ccqb5kq.jpg" alt=""></p><p>我记得我第一次参加一个“不算会议的”会议，起初这是一个混乱的活动，有很多社交和个人项目的分享，但它逐渐凝聚成一个主要是自发组织的技术活动。这一切并没有用魔法，而用的是便签。人们在那些彩色的粘性记事贴上写下演讲和演示的想法，并将它们贴在共同的墙上，其他人将类似的想法分组，最终每个人都知道聚集在哪里讨论特定的话题。这是一件美好而令人满意的见证，它让我对便签有了新的认识。所以我很高兴最近发现 KDE Plasma 桌面有了数字便签，而且在很多方面它们甚至比实体的更有用。该应用叫做 KNotes，如果你有随意的想法想记下来，那么你可能想在自己的 Linux 桌面贴上它。</p><h3 id="安装-knotes" tabindex="-1">安装 KNotes <a class="header-anchor" href="#安装-knotes" aria-label="Permalink to “安装 KNotes”">​</a></h3><p>KNotes 是 Kontact 套件的一部分，这是 KDE 的个人信息管理器（PIM）。如果你正在运行 Plasma 桌面，那么你可能已经安装了 KNotes。如果没有，你可以从包管理器安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install kontact</span></span></code></pre></div><p>在基于 Debian 的发行版上，使用 <code>apt</code> 命令而不是 <code>dnf</code>。</p><h3 id="linux-桌面上的-knotes" tabindex="-1">Linux 桌面上的 KNotes <a class="header-anchor" href="#linux-桌面上的-knotes" aria-label="Permalink to “Linux 桌面上的 KNotes”">​</a></h3><p>尽管 KNotes 是 Kontact 的一部分，但它也是一个可以在后台运行的独立应用，随时可以在你需要时生成空白便签。从你的应用菜单启动 KNotes，它会将自身最小化到你的系统托盘。它的图标是一个黄色的小方块，因为在便签在现实生活中变得丰富多彩之前，它们往往都是黄色的。</p><p>要创建新便签，请右键单击系统托盘中的 KNote 图标并选择 “<ruby>新便签<rt>New Note</rt></ruby>”。第一次创建便签时，系统会提示你选择保存的位置。选择本地 KNotes 数据库文件（它由 Kontact 管理，因此你不会直接与该文件交互）并默认使用此位置。之后就不会再收到这种提示。</p><p>你的桌面上会出现一个新便签，你可以自己在其中输入。</p><p><img src="https://opensource.com/sites/default/files/knote-yellow.jpg" alt="Start using KNotes" title="Start using KNotes"></p><p>就这么简单。至少它可以像这种老式的纸质便签一样。但这些是数字版的 KDE KNotes，因此你可以做的不仅仅是记下一些提醒文本给自己。</p><h3 id="更改便签颜色" tabindex="-1">更改便签颜色 <a class="header-anchor" href="#更改便签颜色" aria-label="Permalink to “更改便签颜色”">​</a></h3><p>当一堆黄色便签开始混合在一起，你可以对便签进行颜色编码。右键单击便签的标题栏（带有日期和时间的部分），然后从出现的上下文菜单中选择 “<ruby>首选项<rt>Preferences</rt></ruby>”。在该窗口中，你可以更改标题和正文字体和字体大小，然后选择 “<ruby>显示设置<rt>Display Settings</rt></ruby>” 选项卡以更改便签纸和字体的颜色。</p><p><img src="https://opensource.com/sites/default/files/knote-color.jpg" alt="KNotes with added color" title="KNotes with added color"></p><h3 id="发送便签" tabindex="-1">发送便签 <a class="header-anchor" href="#发送便签" aria-label="Permalink to “发送便签”">​</a></h3>',18)),a("p",null,[t[2]||(t[2]=e("以前自己写便签的时候，经常会在 ",-1)),o(s,{href:"https://opensource.com/downloads/emacs-cheat-sheet"},{default:n(()=>[...t[0]||(t[0]=[e("Emacs",-1)])]),_:1}),t[3]||(t[3]=e(" 的暂存缓冲区中给自己写一些提醒。有更好的方法来管理 ",-1)),o(s,{href:"https://opensource.com/article/18/7/emacs-modes-note-taking"},{default:n(()=>[...t[1]||(t[1]=[e("Emacs 中的便签",-1)])]),_:1}),t[4]||(t[4]=e("，但是我将便签内容记下后，之后心不在焉地关闭而没保存的习惯很难改掉。",-1))]),t[21]||(t[21]=i('<p>有了 KNotes，便签会自动保存到 Kontact，因此你不必担心需要记着它们。更好的是，它们是数字的，因此你可以将它们发送给自己的其他设备。你可以通过电子邮件将便签发送给自己，也可以通过网络将它们发送到另一台计算机。只需右键单击便签的标题栏，你就可以选择“<ruby>电子邮件<rt>Email</rt></ruby>”或“<ruby>发送<rt>Send</rt></ruby>”。</p><p>要从一个到另一个 KDE Plasma 桌面以 KNotes 方式接收便签，你必须在接收机器上授予 KNotes 接收便签的权限。要允许传入便签，请右键单击系统托盘中的 KNotes 图标并选择 “<ruby>配置 Knotes<rt>Configure KNotes</rt></ruby>”。</p><p><img src="https://opensource.com/sites/default/files/knotes-preferences.jpg" alt="Configure KNotes" title="Configure KNotes"></p><h3 id="设置闹钟" tabindex="-1">设置闹钟 <a class="header-anchor" href="#设置闹钟" aria-label="Permalink to “设置闹钟”">​</a></h3><p>至少对我来说，写便签通常是因为我答应了某人的事情，通常是在短期内，比如一天结束之前。随着我的工作和打开越来越多的窗口，贴在桌面上的便签往往会被掩盖，所以 KNotes 允许你为真正重要的便签设置闹钟，这一点特别有用。</p><p>要为便签设置闹钟，请右键单击便签的标题栏并选择 “<ruby>设置闹钟<rt>Set alarm</rt></ruby>”。</p><h3 id="在-linux-上做便签" tabindex="-1">在 Linux 上做便签 <a class="header-anchor" href="#在-linux-上做便签" aria-label="Permalink to “在 Linux 上做便签”">​</a></h3><p>便笺是记录日常任务的简单而有趣的方法。它们不是对每个人都“有效”，也不是我跟踪每天要做的事情的唯一手段，但它们是很好的选择，而且在一天结束时，在删除已完成的便签前将它们移到“已完成”那一堆，没有什么比这更令人心满意足的了。试一试吧，这是个可能能坚持下去的习惯。</p><hr>',9)),a("p",null,[t[6]||(t[6]=e("via: ",-1)),o(s,{href:"https://opensource.com/article/22/2/sticky-notes-linux-kde"},{default:n(()=>[...t[5]||(t[5]=[e("https://opensource.com/article/22/2/sticky-notes-linux-kde",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=e("作者：",-1)),o(s,{href:"https://opensource.com/users/seth"},{default:n(()=>[...t[7]||(t[7]=[e("Seth Kenlon",-1)])]),_:1}),t[12]||(t[12]=e(" 选题：",-1)),o(s,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[8]||(t[8]=[e("lujun9972",-1)])]),_:1}),t[13]||(t[13]=e(" 译者：",-1)),o(s,{href:"https://github.com/geekpi"},{default:n(()=>[...t[9]||(t[9]=[e("geekpi",-1)])]),_:1}),t[14]||(t[14]=e(" 校对：",-1)),o(s,{href:"https://github.com/wxy"},{default:n(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[17]||(t[17]=e("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[15]||(t[15]=[e("LCTT",-1)])]),_:1}),t[18]||(t[18]=e(" 原创编译，",-1)),o(s,{href:"https://linux.cn/"},{default:n(()=>[...t[16]||(t[16]=[e("Linux中国",-1)])]),_:1}),t[19]||(t[19]=e(" 荣誉推出",-1))])])}const y=r(d,[["render",m]]);export{N as __pageData,y as default};
